{
  "findings": [
    {
      "check_id": "CKV_AWS_79",
      "title": "Instance Metadata Service Version 1 (IMDSv1) is enabled by default",
      "resource": "aws_launch_configuration.levelup-launchconfig",
      "severity": "MEDIUM",
      "explanation": "The launch configuration does not specify `metadata_options`, so it defaults to allowing IMDSv1. This exposes instances to Server-Side Request Forgery (SSRF) attacks that can steal temporary credentials from the metadata service."
    },
    {
      "check_id": "CKV_AWS_8",
      "title": "Elastic Block Store volumes are not encrypted",
      "resource": "aws_launch_configuration.levelup-launchconfig",
      "severity": "MEDIUM",
      "explanation": "The `root_block_device` block is missing, which means the root EBS volume created for these instances will not be encrypted at rest, violating data-at-rest encryption best practices."
    }
  ],
  "patched_code": "resource \"aws_launch_configuration\" \"levelup-launchconfig\" {\n  name_prefix     = \"levelup-launchconfig\"\n  image_id        = lookup(var.AMIS, var.AWS_REGION)\n  instance_type   = \"t2.micro\"\n  key_name        = aws_key_pair.levelup_key.key_name\n\n  metadata_options {\n    http_endpoint               = \"enabled\"\n    http_tokens                 = \"required\"\n    http_put_response_hop_limit = 1\n  }\n\n  root_block_device {\n    encrypted = true\n  }\n}",
  "fix_summary": "Added `metadata_options` with `http_tokens = \"required\"` to enforce IMDSv2 and prevent SSRF credential theft. Added a `root_block_device` block with `encrypted = true` to ensure the root EBS volume is encrypted at rest."
}
